// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceSignalingTransport {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceSignalingTransport = UniffiVTableCallbackInterfaceSignalingTransport(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeSignalingTransport.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface SignalingTransport: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeSignalingTransport.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface SignalingTransport: handle missing in uniffiClone")
            }
        },
        postConnect: { (
            uniffiHandle: UInt64,
            url: RustBuffer,
            body: RustBuffer,
            headers: RustBuffer,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteRustBuffer,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall = {
                () async throws -> Data in
                guard let uniffiObj = try? FfiConverterTypeSignalingTransport.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try await uniffiObj.postConnect(
                     url: try FfiConverterString.lift(url),
                     body: try FfiConverterData.lift(body),
                     headers: try FfiConverterSequenceTypeStringPair.lift(headers)
                )
            }

            let uniffiHandleSuccess = { (returnValue: Data) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: FfiConverterData.lower(returnValue),
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultRustBuffer(
                        returnValue: RustBuffer.empty(),
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsyncWithError(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                lowerError: FfiConverterTypeSignalingError_lower,
                droppedCallback: uniffiOutDroppedCallback
            )
        },
        openWs: { (
            uniffiHandle: UInt64,
            url: RustBuffer,
            headers: RustBuffer,
            uniffiFutureCallback: @escaping UniffiForeignFutureCompleteU64,
            uniffiCallbackData: UInt64,
            uniffiOutDroppedCallback: UnsafeMutablePointer<UniffiForeignFutureDroppedCallbackStruct>
        ) in
            let makeCall = {
                () async throws -> UInt64 in
                guard let uniffiObj = try? FfiConverterTypeSignalingTransport.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return try await uniffiObj.openWs(
                     url: try FfiConverterString.lift(url),
                     headers: try FfiConverterSequenceTypeStringPair.lift(headers)
                )
            }

            let uniffiHandleSuccess = { (returnValue: UInt64) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultU64(
                        returnValue: FfiConverterUInt64.lower(returnValue),
                        callStatus: RustCallStatus()
                    )
                )
            }
            let uniffiHandleError = { (statusCode, errorBuf) in
                uniffiFutureCallback(
                    uniffiCallbackData,
                    UniffiForeignFutureResultU64(
                        returnValue: 0,
                        callStatus: RustCallStatus(code: statusCode, errorBuf: errorBuf)
                    )
                )
            }
            uniffiTraitInterfaceCallAsyncWithError(
                makeCall: makeCall,
                handleSuccess: uniffiHandleSuccess,
                handleError: uniffiHandleError,
                lowerError: FfiConverterTypeSignalingError_lower,
                droppedCallback: uniffiOutDroppedCallback
