// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Event delivered to the application as the response unfolds.
 */

public enum FetchEvent: Equatable, Hashable {
    
    /**
     * Response headers — fires exactly once per fetch on success.
     */
    case head(status: UInt16, headers: [Header]
    )
    /**
     * One body chunk. Multiple chunks are typical for streaming
     * responses; a single fetch may emit `Chunk` zero times for
     * empty bodies and many times for streamed ones.
     */
    case chunk(data: Data
    )
    /**
     * Optional trailer headers received after the body.
     */
    case trailers(headers: [Header]
    )
    /**
     * Stream completed cleanly.
     */
    case end
    /**
     * Stream failed — `code` follows the wire's `ErrorCode`
     * inventory, `message` is the optional human-readable detail.
     */
    case error(code: UInt16, message: Data
    )





}

#if compiler(>=6)
extension FetchEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFetchEvent: FfiConverterRustBuffer {
    typealias SwiftType = FetchEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FetchEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .head(status: try FfiConverterUInt16.read(from: &buf), headers: try FfiConverterSequenceTypeHeader.read(from: &buf)
        )
        
        case 2: return .chunk(data: try FfiConverterData.read(from: &buf)
        )
        
        case 3: return .trailers(headers: try FfiConverterSequenceTypeHeader.read(from: &buf)
        )
        
        case 4: return .end
        
        case 5: return .error(code: try FfiConverterUInt16.read(from: &buf), message: try FfiConverterData.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FetchEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .head(status,headers):
            writeInt(&buf, Int32(1))
            FfiConverterUInt16.write(status, into: &buf)
            FfiConverterSequenceTypeHeader.write(headers, into: &buf)
            
        
        case let .chunk(data):
            writeInt(&buf, Int32(2))
            FfiConverterData.write(data, into: &buf)
            
        
        case let .trailers(headers):
            writeInt(&buf, Int32(3))
            FfiConverterSequenceTypeHeader.write(headers, into: &buf)
            
        
        case .end:
            writeInt(&buf, Int32(4))
        
        
        case let .error(code,message):
            writeInt(&buf, Int32(5))
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterData.write(message, into: &buf)
            
        }
    }
}


