        )
        
        case 3: return .data(streamId: try FfiConverterUInt32.read(from: &buf), endStream: try FfiConverterBool.read(from: &buf), body: try FfiConverterData.read(from: &buf)
        )
        
        case 4: return .end(streamId: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 5: return .err(streamId: try FfiConverterUInt32.read(from: &buf), code: try FfiConverterUInt16.read(from: &buf), message: try FfiConverterData.read(from: &buf)
        )
        
        case 6: return .trailers(streamId: try FfiConverterUInt32.read(from: &buf), headers: try FfiConverterSequenceTypeHeader.read(from: &buf)
        )
        
        case 7: return .wsUpgrade(streamId: try FfiConverterUInt32.read(from: &buf), path: try FfiConverterData.read(from: &buf), headers: try FfiConverterSequenceTypeHeader.read(from: &buf)
        )
        
        case 8: return .wsAccept(streamId: try FfiConverterUInt32.read(from: &buf), headers: try FfiConverterSequenceTypeHeader.read(from: &buf)
        )
        
        case 9: return .wsMsg(streamId: try FfiConverterUInt32.read(from: &buf), opcode: try FfiConverterTypeWireOpcode.read(from: &buf), payload: try FfiConverterData.read(from: &buf)
        )
        
        case 10: return .wsClose(streamId: try FfiConverterUInt32.read(from: &buf), code: try FfiConverterUInt16.read(from: &buf), reason: try FfiConverterData.read(from: &buf)
        )
        
        case 11: return .ping(nonce: try FfiConverterData.read(from: &buf)
        )
        
        case 12: return .pong(nonce: try FfiConverterData.read(from: &buf)
        )
        
        case 13: return .probe(id: try FfiConverterUInt32.read(from: &buf), payload: try FfiConverterData.read(from: &buf)
        )
        
        case 14: return .probeAck(id: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 15: return .goaway(lastAcceptedStreamId: try FfiConverterUInt32.read(from: &buf), code: try FfiConverterUInt16.read(from: &buf), message: try FfiConverterData.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Frame, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .req(streamId,endStream,method,path,headers):
            writeInt(&buf, Int32(1))
            FfiConverterUInt32.write(streamId, into: &buf)
            FfiConverterBool.write(endStream, into: &buf)
            FfiConverterData.write(method, into: &buf)
            FfiConverterData.write(path, into: &buf)
            FfiConverterSequenceTypeHeader.write(headers, into: &buf)
            
        
        case let .res(streamId,endStream,status,headers):
            writeInt(&buf, Int32(2))
            FfiConverterUInt32.write(streamId, into: &buf)
            FfiConverterBool.write(endStream, into: &buf)
            FfiConverterUInt16.write(status, into: &buf)
            FfiConverterSequenceTypeHeader.write(headers, into: &buf)
            
        
        case let .data(streamId,endStream,body):
            writeInt(&buf, Int32(3))
            FfiConverterUInt32.write(streamId, into: &buf)
            FfiConverterBool.write(endStream, into: &buf)
            FfiConverterData.write(body, into: &buf)
            
        
        case let .end(streamId):
            writeInt(&buf, Int32(4))
            FfiConverterUInt32.write(streamId, into: &buf)
            
        
        case let .err(streamId,code,message):
            writeInt(&buf, Int32(5))
            FfiConverterUInt32.write(streamId, into: &buf)
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterData.write(message, into: &buf)
            
        
        case let .trailers(streamId,headers):
            writeInt(&buf, Int32(6))
            FfiConverterUInt32.write(streamId, into: &buf)
            FfiConverterSequenceTypeHeader.write(headers, into: &buf)
            
        
        case let .wsUpgrade(streamId,path,headers):
            writeInt(&buf, Int32(7))
            FfiConverterUInt32.write(streamId, into: &buf)
            FfiConverterData.write(path, into: &buf)
            FfiConverterSequenceTypeHeader.write(headers, into: &buf)
            
        
        case let .wsAccept(streamId,headers):
            writeInt(&buf, Int32(8))
            FfiConverterUInt32.write(streamId, into: &buf)
            FfiConverterSequenceTypeHeader.write(headers, into: &buf)
            
        
        case let .wsMsg(streamId,opcode,payload):
            writeInt(&buf, Int32(9))
            FfiConverterUInt32.write(streamId, into: &buf)
            FfiConverterTypeWireOpcode.write(opcode, into: &buf)
            FfiConverterData.write(payload, into: &buf)
            
        
        case let .wsClose(streamId,code,reason):
            writeInt(&buf, Int32(10))
            FfiConverterUInt32.write(streamId, into: &buf)
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterData.write(reason, into: &buf)
            
        
        case let .ping(nonce):
            writeInt(&buf, Int32(11))
            FfiConverterData.write(nonce, into: &buf)
            
        
        case let .pong(nonce):
            writeInt(&buf, Int32(12))
            FfiConverterData.write(nonce, into: &buf)
            
        
        case let .probe(id,payload):
            writeInt(&buf, Int32(13))
            FfiConverterUInt32.write(id, into: &buf)
            FfiConverterData.write(payload, into: &buf)
            
        
        case let .probeAck(id):
            writeInt(&buf, Int32(14))
            FfiConverterUInt32.write(id, into: &buf)
            
        
        case let .goaway(lastAcceptedStreamId,code,message):
            writeInt(&buf, Int32(15))
            FfiConverterUInt32.write(lastAcceptedStreamId, into: &buf)
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterData.write(message, into: &buf)
            
        }
    }
}


