    case req = 1
    case res = 2
    case data = 3
    case end = 4
    case err = 5
    case trailers = 6
    case wsUpgrade = 16
    case wsAccept = 17
    case wsMsg = 18
    case wsClose = 19
    case ping = 32
    case pong = 33
    case probe = 48
    case probeAck = 49
    case goaway = 127





}

