        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .req
        
        case 2: return .res
        
        case 3: return .data
        
        case 4: return .end
        
        case 5: return .err
        
        case 6: return .trailers
        
        case 7: return .wsUpgrade
        
        case 8: return .wsAccept
        
        case 9: return .wsMsg
        
        case 10: return .wsClose
        
        case 11: return .ping
        
        case 12: return .pong
        
        case 13: return .probe
        
        case 14: return .probeAck
        
        case 15: return .goaway
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FrameKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case .req:
            writeInt(&buf, Int32(1))
        
        
        case .res:
            writeInt(&buf, Int32(2))
        
        
        case .data:
            writeInt(&buf, Int32(3))
        
        
        case .end:
            writeInt(&buf, Int32(4))
        
        
        case .err:
            writeInt(&buf, Int32(5))
        
        
        case .trailers:
            writeInt(&buf, Int32(6))
        
        
        case .wsUpgrade:
            writeInt(&buf, Int32(7))
        
        
        case .wsAccept:
            writeInt(&buf, Int32(8))
        
        
        case .wsMsg:
            writeInt(&buf, Int32(9))
        
        
        case .wsClose:
            writeInt(&buf, Int32(10))
        
        
        case .ping:
            writeInt(&buf, Int32(11))
        
        
        case .pong:
            writeInt(&buf, Int32(12))
        
        
        case .probe:
            writeInt(&buf, Int32(13))
        
        
