    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> WsEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .`open`(headers: try FfiConverterSequenceTypeHeader.read(from: &buf)
        )
        
        case 2: return .message(binary: try FfiConverterBool.read(from: &buf), data: try FfiConverterData.read(from: &buf)
        )
        
        case 3: return .close(code: try FfiConverterUInt16.read(from: &buf), reason: try FfiConverterData.read(from: &buf)
        )
        
        case 4: return .error(message: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: WsEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .`open`(headers):
            writeInt(&buf, Int32(1))
            FfiConverterSequenceTypeHeader.write(headers, into: &buf)
            
        
        case let .message(binary,data):
            writeInt(&buf, Int32(2))
            FfiConverterBool.write(binary, into: &buf)
            FfiConverterData.write(data, into: &buf)
            
        
        case let .close(code,reason):
            writeInt(&buf, Int32(3))
            FfiConverterUInt16.write(code, into: &buf)
            FfiConverterData.write(reason, into: &buf)
            
        
        case let .error(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


